function ratingStars(value){const n=Math.max(0,Math.min(5,Math.round(Number(value)||0)));return '★'.repeat(n)+'☆'.repeat(5-n)}
function renderHomepageFeedback(){const section=$('.trust-panels .reviews'),panel=$('#homepageFeedbackContent');if(!panel||!section)return;const review=homepageReviewState.review;section.hidden=!(SHOW_HOMEPAGE_REVIEWS&&review);section.closest('.trust-panels')?.classList.toggle('show-home-reviews',!section.hidden);if(!SHOW_HOMEPAGE_REVIEWS||!review)return;const t=words[language],eyebrow=$('#customerFeedbackEyebrow'),title=$('#customerFeedbackTitle');if(eyebrow)eyebrow.textContent=t.reviewEyebrow;if(title)title.textContent=t.reviewTitle;if(homepageReviewState.status==='loading'||homepageReviewState.status==='error'||!review)return;const name=language==='bn'?(review.product?.name_bn||review.product?.name_en):(review.product?.name_en||review.product?.name_bn);panel.innerHTML=`<p class="homepage-review-rating"><span class="rating-stars">${ratingStars(review.rating)}</span><b>${Number(review.rating)} / 5</b>${name?`<span class="homepage-review-product">· ${escapeHtml(name)}</span>`:''}</p>${review.review_text?`<blockquote>“${escapeHtml(review.review_text)}”</blockquote>`:`<p class="feedback-empty">${language==='bn'?'একজন যাচাইকৃত ক্রেতা এই পণ্যে রেটিং দিয়েছেন।':'A verified customer rated this product.'}</p>`}<small class="homepage-review-note">— ${t.verifiedBuyer}</small>`}
async function loadHomepageFeedback(){
  const panel=$('#homepageFeedbackContent');if(!panel)return;
  if(!supabaseClient){homepageReviewState={status:'empty',review:null};renderHomepageFeedback();return;}
  const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);
  try{
    const {data,error}=await supabaseClient.from('product_reviews').select('rating,review_text,created_at,product_id').order('created_at',{ascending:false}).limit(1).abortSignal(controller.signal).maybeSingle();
    if(error)throw error;
    let review=data||null;
    if(review?.product_id){const product=await supabaseClient.from('products').select('name_en,name_bn').eq('id',review.product_id).maybeSingle();if(!product.error)review.product=product.data;}
    homepageReviewState={status:review?'ready':'empty',review};
  }catch{homepageReviewState={status:'error',review:null};}
  finally{clearTimeout(timeout);renderHomepageFeedback();}
}
async function loadProductRatings(refreshGrid=true){if(!supabaseClient)return;const {data,error}=await supabaseClient.from('product_reviews').select('product_id,rating');if(error){console.warn('Could not load product ratings');return}productRatings.clear();for(const row of data||[]){const item=productRatings.get(row.product_id)||{sum:0,count:0};item.sum+=Number(row.rating)||0;item.count++;productRatings.set(row.product_id,item)}for(const item of productRatings.values())item.average=item.sum/item.count;if(refreshGrid)renderProducts($('#searchInput').value)}
