function quantityLimit(p){const stock=Number(p?.stockQuantity);return Math.max(0,Math.min(MAX_ORDER_QUANTITY,Number.isFinite(stock)?stock:MAX_ORDER_QUANTITY));}
function normalizeCartQuantities(checkStock=false){let adjusted=false;for(const [id,value] of Object.entries(cart)){const p=products.find(item=>item.id===id),max=p&&checkStock?quantityLimit(p):MAX_ORDER_QUANTITY,quantity=Math.max(0,Math.floor(Number(value)||0)),next=Math.min(max,quantity);if(next!==quantity)adjusted=true;if(next)cart[id]=next;else delete cart[id];}if(adjusted)writeStoredValue('frostly-cart',JSON.stringify(cart));return adjusted;}
