function addItem(id,quantity=1){const p=products.find(item=>item.id===id),max=quantityLimit(p),next=(cart[id]||0)+Math.max(1,Math.floor(Number(quantity)||1));if(next>max){toast(max>=MAX_ORDER_QUANTITY?words[language].maxCartQuantity:words[language].stockLimit);return false;}cart[id]=next;saveCart();renderProducts($('#searchInput').value);toast(words[language].cartAdded);return true;}
function renderCart(){const t=words[language];let count=Object.values(cart).reduce((a,b)=>a+b,0);$('#cartCount').textContent=count;const rows=Object.entries(cart).filter(([id,q])=>q>0&&products.some(p=>p.id===id));const checkoutButton=$('#checkoutButton');if(checkoutButton)checkoutButton.disabled=!rows.length;$('#cartItems').innerHTML=rows.length?rows.map(([id,q])=>{let p=products.find(x=>x.id===id),max=quantityLimit(p);return `<div class="cart-line"><img loading="lazy" width="600" height="480" src="${escapeHtml(productImage(p))}" alt="${escapeHtml(language==='en'?p.en:p.name)}"/><div><b>${escapeHtml(language==='en'?p.en:p.name)}</b><small>৳ ${Number(p.price)} · ${escapeHtml(language==='en'?p.weightEn:p.weight)}</small><div class="qty"><button data-qty="${escapeHtml(id)}" data-delta="-1" aria-label="${language==='en'?'Decrease quantity':'পরিমাণ কমান'}">−</button><span>${Number(q)}</span><button data-qty="${escapeHtml(id)}" data-delta="1" aria-label="${language==='en'?'Increase quantity':'পরিমাণ বাড়ান'}" ${q>=max?'disabled title="'+escapeHtml(max>=MAX_ORDER_QUANTITY?t.maxCartQuantity:t.stockLimit)+'"':''}>＋</button></div></div><span class="line-price">৳ ${Number(p.price)*Number(q)}</span></div>`}).join(''):`<div class="empty-cart animated-empty-cart"><div class="empty-cart-art" aria-hidden="true"><span class="cart-spark spark-one">✦</span><span class="cart-spark spark-two">✧</span><svg viewBox="0 0 96 82"><path class="cart-handle" d="M20 23h8l8 37h40l9-27H32"/><path class="cart-basket" d="M33 39h46l-5 18H37Z"/><path class="cart-wheel" d="M43 69a3 3 0 1 0 0 6 3 3 0 0 0 0-6ZM68 69a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z"/><path class="cart-ground" d="M27 78h55"/></svg><span class="empty-cart-orbit"></span></div><h3>${language==='en'?'Your cart is taking a little break':'আপনার কার্ট এখন বিশ্রামে'}</h3><p>${language==='en'?'Find something delicious to bring home.':'পছন্দের কিছু খাবার খুঁজে কার্টে যোগ করুন।'}</p><button type="button" id="emptyCartBrowse" class="button primary">${language==='en'?'Explore products':'পণ্য দেখুন'} <span aria-hidden="true">→</span></button></div>`;let total=rows.reduce((a,[id,q])=>a+products.find(p=>p.id===id).price*q,0);$('#cartSubtotal').textContent=`৳ ${total.toLocaleString('en-BD')}`;$('#emptyCartBrowse')?.addEventListener('click',()=>{setOverlay('cartOverlay',false);activeCategory='';$('#searchInput').value='';renderProducts('');$('#bestsellers').scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const id=b.dataset.qty,p=products.find(item=>item.id===id),next=(cart[id]||0)+Number(b.dataset.delta),max=quantityLimit(p);if(next>max){toast(max>=MAX_ORDER_QUANTITY?t.maxCartQuantity:t.stockLimit);return;}cart[id]=Math.max(0,next);if(!cart[id])delete cart[id];saveCart();});}
