function addBubble(text,who){const el=document.createElement('div');el.className=`bubble ${who}`;el.textContent=text;$('#chatBody').appendChild(el);el.scrollIntoView({block:'end'});}function answer(text){const lower=text.toLowerCase(),t=words[language];if(/500|৫০০/.test(lower)){const picks=products.filter(p=>p.price<=500).slice(0,3);return `${t.searchBudget} ${picks.map(p=>`${language==='en'?p.en:p.name} (৳${p.price})`).join(', ')}. ${t.chatNote}`;}const match=products.filter(p=>(`${p.name} ${p.en} ${p.category} ${p.categoryEn}`).toLowerCase().includes(lower.replace(/show|me|products|দেখান|দরকার|চাই|পণ্য/g,'').trim())||lower.includes((language==='en'?p.categoryEn:p.category).toLowerCase().slice(0,3)));if(match.length)return `${t.chatFound} ${match.slice(0,3).map(p=>`${language==='en'?p.en:p.name}, ${language==='en'?p.weightEn:p.weight}, ৳${p.price}`).join(' · ')}. ${t.chatNote}`;return t.chatFallback;}
const assistantHistory=[];
let assistantRequestPending=false;
let assistantNextAllowedAt=0;
function createAssistantPayload(){
  const messages=assistantHistory.slice(-8).map(item=>({role:item.role,content:String(item.content).trim().slice(0,500)}));
  const catalog=products.slice(0,30).map(p=>({nameEn:p.en,nameBn:p.name,packEn:p.weightEn,packBn:p.weight,price:Number(p.price),inStock:Number(p.stockQuantity)>0}));
  let body;
  const serialize=()=>JSON.stringify({messages,products:catalog});
  body=serialize();
  while(new TextEncoder().encode(body).byteLength>3900&&messages.length>1){messages.shift();body=serialize();}
  while(new TextEncoder().encode(body).byteLength>3900&&catalog.length){catalog.pop();body=serialize();}
  return body;
}
$('#chatForm').onsubmit=async e=>{
  e.preventDefault();
  const input=$('#chatInput'),button=$('.chat-form button'),message=input.value.trim().slice(0,500);
  if(!message||assistantRequestPending||Date.now()<assistantNextAllowedAt)return;
  addBubble(message,'user');
  input.value='';
  if(productCatalogState!=='loaded'||!products.length){addBubble(words[language].chatCatalogError,'assistant');return;}
  assistantHistory.push({role:'user',content:message});
  while(assistantHistory.length>8)assistantHistory.shift();
  assistantRequestPending=true;
  assistantNextAllowedAt=Date.now()+2000;
  button.disabled=true;
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),20000);
  try{
    const response=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:createAssistantPayload(),signal:controller.signal});
    const data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(data.error||'Assistant unavailable.');
    const reply=typeof data.reply==='string'?data.reply:'Sorry, I could not prepare an answer.';
    addBubble(reply,'assistant');
    assistantHistory.push({role:'assistant',content:reply});
    while(assistantHistory.length>8)assistantHistory.shift();
  }catch{
    const catalogReply=answer(message);
    const fallback=language==='bn'?`AI সহকারী এখন সাময়িকভাবে ব্যস্ত। ক্যাটালগ থেকে: ${catalogReply}`:`The AI assistant is temporarily unavailable. From the catalog: ${catalogReply}`;
    addBubble(fallback,'assistant');
    assistantHistory.push({role:'assistant',content:fallback});
    while(assistantHistory.length>8)assistantHistory.shift();
  }finally{
    clearTimeout(timeout);
    assistantRequestPending=false;
    const remaining=assistantNextAllowedAt-Date.now();
    if(remaining>0)setTimeout(()=>{if(!assistantRequestPending)button.disabled=false;},remaining);
    else button.disabled=false;
    input.focus();
  }
};
