const aw=()=>accountWords[language];
function supabaseMessage(error){const message=String(error?.message||'');if(/Supabase is temporarily unavailable|Failed to fetch|NetworkError|Load failed/i.test(message))return language==='bn'?'স্টোরের সাথে এখন সংযোগ করা যাচ্ছে না। কিছুক্ষণ পর আবার চেষ্টা করুন। অর্ডারটি হয়েছে কি না নিশ্চিত না হলে, আবার দেওয়ার আগে আপনার অর্ডার তালিকা দেখুন।':'We can’t connect to the store right now. Please try again shortly. If you’re unsure whether your order went through, check My orders before trying again.';return message||aw().loadError;}
function showAccountError(message){const el=$('#authMessage');if(el){el.hidden=false;el.textContent=message;el.classList.add('auth-error');}}
function updateSignInPlaceholder(){const input=$('#signinIdentity');if(!input)return;input.placeholder=window.matchMedia('(max-width: 419px)').matches?aw().signinMobilePlaceholder:aw().signinPlaceholder;}
window.addEventListener('resize',updateSignInPlaceholder,{passive:true});
