function orderStatusLabel(status){const t=aw();return ({pending_confirmation:t.pending,confirmed:t.confirmed,preparing:t.preparing,packed:t.packed,out_for_delivery:t.out,delivered:t.delivered,cancelled:t.cancelled})[status]||status;}
  function formatOrderReference(order){const hex=String(order.id||'').replace(/-/g,'');if(/^[0-9a-f]{32}$/i.test(hex)){let binary='';for(let i=0;i<hex.length;i+=2)binary+=String.fromCharCode(parseInt(hex.slice(i,i+2),16));const token=btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/g,'');return `#FST-${token.slice(-5).toUpperCase()}`}const fallback=String(order.order_number||order.id||'ORDER').replace(/[^a-z0-9]/gi,'').toUpperCase();return `#FST-${fallback.slice(-5)||'ORDER'}`}
function normalizeBangladeshPhone(value){const compact=String(value||'').trim().replace(/[\s()-]/g,'');if(/^01[3-9]\d{8}$/.test(compact))return `+880${compact.slice(1)}`;if(/^\+?8801[3-9]\d{8}$/.test(compact))return compact.startsWith('+')?compact:`+${compact}`;return '';}
function customerOrderStatus(orderStatus){const t=aw();if(orderStatus==='pending_confirmation')return {label:t.pendingShort,className:'status-pending',step:0};if(orderStatus==='cancelled')return {label:t.cancelled,className:'status-cancelled',step:-1};if(orderStatus==='delivered')return {label:t.delivered,className:'status-delivered',step:3};if(orderStatus==='out_for_delivery')return {label:t.progressOnWay,className:'status-on-way',step:2};return {label:t.progressConfirmed,className:'status-confirmed',step:1};}
function formatCustomerOrderDate(value){const date=new Date(value);if(Number.isNaN(date.getTime()))return '';const locale=language==='bn'?'bn-BD':'en-GB',parts=new Intl.DateTimeFormat(locale,{timeZone:'Asia/Dhaka',day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}).formatToParts(date),part=type=>parts.find(item=>item.type===type)?.value||'';return `${part('day')} ${part('month')} ${part('year')}, ${part('hour')}:${part('minute')} ${part('dayPeriod').toUpperCase()}`;}
function renderCustomerOrderProgress(orderStatus){const t=aw(),meta=customerOrderStatus(orderStatus);if(meta.step<0)return '';const labels=[t.progressPlaced,t.progressConfirmed,t.progressOnWay,t.progressDelivered],steps=labels.map((label,index)=>`<li class="${index<meta.step?'is-done':index===meta.step?'is-current':''}"><span class="order-progress-dot" aria-hidden="true"></span><span>${label}</span></li>`).join('');return `<div class="customer-order-progress" aria-label="${language==='bn'?'অর্ডার ডেলিভারির অগ্রগতি':'Order delivery progress'}" style="--order-progress:${meta.step/3*75}%"><ol>${steps}</ol></div>${orderStatus==='pending_confirmation'?`<p class="customer-order-status-help">${t.pendingHelper}</p>`:''}`;}
function renderCustomerOrderCards(rows,filter='all'){
  const visible=rows.filter(order=>filter==='all'||filter==='delivered'&&order.status==='delivered'||filter==='cancelled'&&order.status==='cancelled'||filter==='active'&&!['delivered','cancelled'].includes(order.status));
  if(!visible.length)return `<p class="order-list-empty">${rows.length?aw().noMatchingOrders:aw().noOrders}</p>`;
  const paymentLabels={cod:aw().methodCod,bkash:aw().methodBkash,nagad:aw().methodNagad,rocket:aw().methodRocket};
  return visible.map(order=>{
    const items=order.order_items||[],subtotal=Number(order.subtotal_bdt||items.reduce((sum,item)=>sum+Number(item.unit_price_bdt||0)*Number(item.quantity||0),0)),fee=Number(order.delivery_fee_bdt||0),total=Number(order.total_bdt||subtotal+fee),paymentLabel=paymentLabels[order.payment_method]||order.payment_method||'—',paymentStatus=order.payment_status==='pending_verification'?aw().paymentPending:order.payment_status==='collected'?aw().paymentCollected:order.payment_status||'';
    return `<details class="customer-order"><summary><span class="customer-order-ref"><b>${formatOrderReference(order)}</b><small>${formatCustomerOrderDate(order.created_at)}</small></span><span class="customer-order-summary"><b class="customer-order-total">৳ ${total.toLocaleString('en-BD')}</b><span class="order-status ${customerOrderStatus(order.status).className}">${customerOrderStatus(order.status).label}</span></span><i class="customer-order-chevron" aria-hidden="true"></i></summary><div class="customer-order-body"><div class="customer-order-reorder-row"><button type="button" class="customer-order-reorder-button" data-reorder-order="${escapeHtml(order.id)}">${language==='bn'?'এই অর্ডার আবার করুন':'Reorder these items'}</button></div>${renderCustomerOrderProgress(order.status)}<h4>${aw().orderedProducts} <span>(${items.length})</span></h4><div class="customer-order-items">${items.map(item=>{const reviewProduct=products.find(product=>product.dbId===item.product_id);return `<div class="customer-order-item"><span><b>${escapeHtml(language==='bn'?item.product_name_bn:item.product_name_en)}</b><small>${Number(item.quantity)} × ৳ ${Number(item.unit_price_bdt||0).toLocaleString('en-BD')}</small>${order.status==='delivered'&&reviewProduct?`<button type="button" class="customer-order-rate-button" data-order-review="${escapeHtml(reviewProduct.id)}">${aw().rateProduct}</button>`:''}</span><strong>৳ ${Number(item.line_total_bdt||Number(item.unit_price_bdt||0)*Number(item.quantity||0)).toLocaleString('en-BD')}</strong></div>`}).join('')||`<p>${aw().noOrderItems}</p>`}</div><div class="customer-order-totals"><div><span>${aw().subtotal}</span><b>৳ ${subtotal.toLocaleString('en-BD')}</b></div><div><span>${aw().deliveryFee}</span><b>৳ ${fee.toLocaleString('en-BD')}</b></div><div class="customer-order-grand"><strong>${aw().total}</strong><strong>৳ ${total.toLocaleString('en-BD')}</strong></div></div><div class="customer-order-delivery"><b>${aw().deliveryDetails}</b><span>${escapeHtml(order.delivery_area||'')}</span><small>${escapeHtml(order.delivery_address||'')}</small></div><div class="customer-order-delivery"><b>${aw().choosePayment}</b><span>${escapeHtml(paymentLabel)}</span><small>${escapeHtml(paymentStatus)}${order.payment_reference?` · ${escapeHtml(aw().transactionId)}: ${escapeHtml(order.payment_reference)}`:''}</small></div>${order.status==='pending_confirmation'?`<div class="customer-order-actions"><button type="button" class="customer-order-cancel-button" data-cancel-order="${escapeHtml(order.id)}">${aw().cancelOrder}</button><small>${aw().cancelBeforeConfirm}</small></div>`:''}</div></details>`;
  }).join('');
}

function bindCustomerOrderReorderButtons(root,orders){root.querySelectorAll('[data-reorder-order]').forEach(button=>button.onclick=event=>{event.preventDefault();event.stopPropagation();const order=orders.find(item=>String(item.id)===button.dataset.reorderOrder);if(!order)return;let added=0,skipped=0;for(const item of order.order_items||[]){const product=products.find(candidate=>String(candidate.dbId)===String(item.product_id));if(!product||quantityLimit(product)<1){skipped++;continue}const requested=Math.max(1,Math.floor(Number(item.quantity)||1)),available=quantityLimit(product)-(cart[product.id]||0),quantity=Math.min(requested,Math.max(0,available));if(quantity){cart[product.id]=(cart[product.id]||0)+quantity;added+=quantity}if(quantity<requested)skipped++}if(!added){toast(language==='bn'?'এই অর্ডারের কোনো পণ্য এখন স্টকে নেই।':'None of these items are currently available.');return}saveCart();renderCart();renderProducts($('#searchInput').value);setOverlay('ordersOverlay',false);setOverlay('cartOverlay',true);toast(language==='bn'?`${added}টি পণ্য কার্টে যোগ হয়েছে${skipped?` · ${skipped}টি বাদ`:''}`:`${added} item${added===1?'':'s'} added to your cart${skipped?` · ${skipped} unavailable or over the stock limit`:''}`)})}
function bindCustomerOrderCancelButtons(root,afterCancel){root.querySelectorAll('[data-cancel-order]').forEach(button=>button.onclick=async event=>{event.preventDefault();event.stopPropagation();if(!supabaseClient){toast(aw().loadError);return}if(!window.confirm(aw().cancelOrderConfirm))return;button.disabled=true;try{const {error}=await supabaseClient.rpc('customer_cancel_order',{p_order_id:button.dataset.cancelOrder});if(error)throw error;toast(aw().orderCancelled);await afterCancel?.()}catch(error){const message=String(error?.message||'');toast(message.includes('Only pending')||message.includes('only be cancelled')?aw().cancelNotAvailable:`${aw().cancelOrderError} ${supabaseMessage(error)}`);button.disabled=false}})}
